import{KEY,uid,clone,seed,composition,check,blocked,fingerprint,reconcile,audit,allow,submit,transition,review,saveIngredient,affectedDishes,orderStatus,scenarios,loadScenario}from'./engine.mjs';
const $=s=>document.querySelector(s),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',menu:'M4 3v7a3 3 0 0 0 6 0V3 M7 3v18 M18 3c-3 4-4 8 0 9h2V3z M20 12v9',orders:'M7 3h10v3H7z M5 5H3v16h18V5h-2 M7 11h10 M7 15h7',kitchen:'M7 15h10v6H7z M7 15V9a4 4 0 1 1 2-7 4 4 0 0 1 6 0 4 4 0 1 1 2 7v6 M10 18h4',shield:'M12 3l8 3v6c0 5-8 9-8 9s-8-4-8-9V6z M9 12l2 2 4-4',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M9 3l-1 3-3 1-2 3 2 3v3l3 2 1 3h6l1-3 3-2v-3l2-3-2-3-3-1-1-3z',plus:'M12 5v14 M5 12h14',arrow:'M5 12h14 M14 7l5 5-5 5',chevron:'M9 5l7 7-7 7',down:'M6 9l6 6 6-6',clock:'M12 8v5l3 2 M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',users:'M9 12a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M2 21v-2a6 6 0 0 1 12 0v2 M17 4a4 4 0 0 1 0 8 M18 15a5 5 0 0 1 4 5',alert:'M12 3L2 21h20z M12 9v5 M12 17v.2',check:'M5 12l4 4L19 6',x:'M6 6l12 12 M6 18L18 6',search:'M21 21l-5-5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9 M10 21h4',help:'M9 8a3 3 0 1 1 4 3c-1 1-1 2-1 3 M12 17v.2 M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',leaf:'M20 3C8 2 2 9 6 16s16 1 14-13z M5 21L16 9',edit:'M15 4l5 5 M4 16L16 4a3 3 0 0 1 4 4L8 20H4z',history:'M3 4v6h6 M3 10a9 9 0 1 1 1 8 M12 7v6l4 2',table:'M3 7h18v5H3z M5 12v9 M19 12v9 M8 3h8',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12 M15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0',book:'M12 5C8 2 3 3 3 3v16s5-1 9 2c4-3 9-2 9-2V3s-5-1-9 2z M12 5v16',trash:'M3 6h18 M9 6V3h6v3 M5 6l1 15h12l1-15 M10 10v7 M14 10v7',copy:'M8 8h13v13H8z M16 4V2H2v14h2',download:'M12 3v12 M7 10l5 5 5-5 M4 16v5h16v-5',spark:'M12 2l3 7 7 3-7 3-3 7-3-7-7-3 7-3z'};
const icon=(n,cls='')=>`<svg class="${cls}" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[n]||icons.grid}"/></svg>`;
const btn=(label,action,cls='',attrs='')=>`<button type="button" class="button ${cls}" data-action="${action}" ${attrs}>${label}</button>`;
const money=n=>new Intl.NumberFormat('en-GB',{style:'currency',currency:'GBP'}).format(n);
const fmt=d=>new Date(d).toLocaleString('en-GB',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'});
const elapsed=d=>Math.max(0,Math.floor((Date.now()-new Date(d))/60000));
const statusBadge=status=>{const colors={'awaiting review':'amber',draft:'gray',received:'blue','in preparation':'blue',ready:'green',served:'gray',canceled:'gray'};return`<span class="badge ${colors[status]||'gray'}">${icon(status==='awaiting review'?'alert':status==='ready'||status==='served'?'check':'clock')}${esc(state.settings.statusLabels?.[status]||(status[0]?.toUpperCase()+status.slice(1)))}</span>`;};
let state;try{state=JSON.parse(localStorage.getItem(KEY));if(state?.schema!==1)state=seed();}catch{state=seed();}
let role=sessionStorage.getItem('mise-role')||'Waitstaff';if(!['Waitstaff','Kitchen','Administration'].includes(role))role='Waitstaff';
let page='dashboard',selectedTable='table-4',adminTab='Menu',menuCategory='All dishes',menuSearch='',tableFilter='All tables',orderFilter='All',kitchenFilter='Active',modalCleanup=null;
const modalRoot=$('#modal-root');let lastFocus;
const table=id=>state.tables.find(t=>t.id===id),dish=id=>state.dishes.find(d=>d.id===id),order=id=>state.orders.find(o=>o.id===id);
const liveOrders=t=>state.orders.filter(o=>o.table===t.id&&o.items.some(i=>!['served','canceled'].includes(i.status)));
const total=o=>o.items.filter(i=>i.status!=='canceled').reduce((n,i)=>n+(dish(i.dish)?.price||0)*i.quantity,0);
const activeItems=()=>state.orders.flatMap(o=>o.items.filter(i=>!['served','canceled'].includes(i.status)).map(i=>({o,i})));
const findings=()=>activeItems().filter(({o,i})=>blocked(state,o,i));
const canEditOrder=()=>role!=='Kitchen';
function toast(message,error=false){const el=$('#toast');el.textContent=message;el.className='show'+(error?' error':'');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.className='',4200);}
function save(){reconcile(state);try{localStorage.setItem(KEY,JSON.stringify(state));}catch{toast('Browser storage is unavailable or full. Export your demonstration data before continuing.',true);}}
function mutate(action,message,close=true){const backup=clone(state);try{if(!state.users.some(u=>u.role===role&&u.active))throw Error('No active demonstration profile is available for this role. Choose Administration to enable a profile.');action();save();if(close)closeModal();render();if(message)toast(message);return true;}catch(e){state=backup;const err=$('.form-error');if(err){err.textContent=e.message;err.classList.add('error-text');}else toast(e.message,true);return false;}}
function nav(p,t){page=p;if(t)selectedTable=t;if(p==='admin'&&role!=='Administration'){page='dashboard';toast('Choose Administration in the simulated role selector.',true);}history.replaceState(null,'',`#${page}${page==='table'?'/'+selectedTable:''}`);render();window.scrollTo({top:0,behavior:'instant'});}
function closeModal(){modalCleanup?.();modalCleanup=null;modalRoot.innerHTML='';document.body.style.overflow='';lastFocus?.focus?.();}
function modal(title,subtitle,body,footer='',wide=false){lastFocus=document.activeElement;modalCleanup?.();modalCleanup=null;modalRoot.innerHTML=`<div class="modal-overlay"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="dialog-title" tabindex="-1"><header class="modal-head"><div><h2 id="dialog-title">${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div><button class="icon-btn" data-action="close" aria-label="Close dialog">${icon('x')}</button></header><div class="modal-body"><div class="form-error" role="alert"></div>${body}</div>${footer?`<footer class="modal-footer">${footer}</footer>`:''}</section></div>`;document.body.style.overflow='hidden';$('.modal').focus();}
const labelRestriction=r=>`${r.type[0].toUpperCase()+r.type.slice(1)} · ${(r.target==='allergen'?state.allergens:state.ingredients).find(x=>x.id===r.id)?.name||r.id}`;
function alertBox(a){return`<div class="warning-box ${a.type}" role="note">${icon(a.type==='direct'?'alert':'shield')}<div><strong>${a.type==='direct'?'ALLERGY / RESTRICTION ALERT':a.type==='potential'?'POTENTIAL RISK':'INCOMPLETE INFORMATION'} · ${esc(a.diner)}</strong>${esc(a.restriction)} — ${esc(a.detail)}<span class="path">${esc(a.path.join(' → '))}</span></div></div>`;}
function checksHTML(o,i,limit=Infinity){const all=check(state,o,i);return all.length?all.slice(0,limit).map(alertBox).join('')+(all.length>limit?`<p class="help-text mt">+ ${all.length-limit} more finding${all.length-limit===1?'':'s'} · Open details for all relationships.</p>`:''):`<div class="clear-box">${icon('check')}<div>No matches detected<small>Based on available information. This is not a guarantee of suitability.</small></div></div>`;}
function pageHeading(title,sub,actions='',eyebrow=''){return`<div class="page-heading"><div>${eyebrow?`<div class="eyebrow">${eyebrow}</div>`:''}<h1>${title}</h1><p class="subtitle">${sub}</p></div><div class="actions">${actions}</div></div>`;}
const demoNotice=()=>`<div class="notice">${icon('shield')}<div><strong>Demonstration using fictional data.</strong> Do not use to manage real allergies without validation and restaurant procedures.</div></div>`;
function render(){reconcile(state);const alerts=findings().length;const names={dashboard:'Service overview',menu:'Menu & ingredients',orders:'Orders',kitchen:'Kitchen',reviews:'Dietary reviews',admin:'Administration',table:table(selectedTable)?.name||'Table'};if(page==='admin'&&role!=='Administration')page='dashboard';
$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><div class="brand-mark">${icon('leaf')}</div><div class="brand-text"><div class="brand-name">mise<span style="color:#a0ae8f">.</span></div><small>CARE IN EVERY SERVICE</small></div></div><div class="nav-label">WORKSPACE</div><nav class="nav" aria-label="Main navigation">${[['dashboard','grid','Overview'],['menu','menu','Menu'],['orders','orders','Orders'],['kitchen','kitchen','Kitchen'],['reviews','shield','Dietary reviews'],...(role==='Administration'?[['admin','settings','Administration']]:[])].map(([p,ic,n])=>`<button aria-label="${n}" title="${n}" data-action="nav" data-page="${p}" class="${page===p||(p==='orders'&&page==='table')?'active':''}" ${page===p?'aria-current="page"':''}>${icon(ic)}<span>${n}</span>${p==='reviews'&&alerts?`<span class="count">${alerts}</span>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="demo-card"><strong>${icon('spark')} A space to try things</strong>This is your demonstration workspace. Explore every part of a thoughtful service.${btn('Load sample scenario '+icon('arrow'),'scenarios','text sm','style="padding:8px 0 0;font-size:9px"')}</div><div class="profile"><span class="avatar">${role==='Waitstaff'?'AM':role==='Kitchen'?'JC':'ST'}</span><div class="profile-info"><strong>${esc(state.users.find(u=>u.role===role&&u.active)?.name||'Demo profile')}</strong><small>${esc(role)} · Demo profile</small></div></div></div></aside><main class="main"><header class="topbar"><div class="crumb">${icon('table')}<span>${esc(state.settings.restaurant)}</span><span>/</span><b>${names[page]}</b></div><div class="top-right"><span class="live"><span class="dot"></span>${esc(state.settings.service)}</span><label class="role-switch" title="Simulated access only. Production requires server-side authentication and authorization.">${icon('users')}<span>Viewing as</span><select id="role-select" aria-label="Demonstration role">${['Waitstaff','Kitchen','Administration'].map(r=>`<option ${r===role?'selected':''}>${r}</option>`).join('')}</select></label><button class="icon-btn notification-dot" data-action="nav" data-page="reviews" aria-label="Dietary reviews">${icon('bell')}</button><button class="icon-btn" data-action="help" aria-label="About this demonstration">${icon('help')}</button></div></header><div class="content">${({dashboard:dashboard,menu:menuPage,orders:ordersPage,kitchen:kitchenPage,reviews:reviewsPage,admin:adminPage,table:tablePage}[page]||dashboard)()}<footer class="footnote"><span>${icon('shield')} A little more care, from the first ingredient to the final plate.</span><span>Fictional data · Browser storage · ${btn('About this demo','help','text sm','style="font-size:9px;padding:0;min-height:0"')}</span></footer></div></main></div>`;
}
function stat(label,value,ic,note,warn=false){return`<div class="stat ${warn?'warn':''}"><div class="stat-label">${label}<span class="stat-icon">${icon(ic)}</span></div><div class="stat-value">${value}</div><div class="stat-note"><span class="dot" ${warn?'style="background:#caa267"':''}></span>${note}</div></div>`;}
function dashboard(){const occupied=state.tables.filter(t=>liveOrders(t).length||t.diners.length);const active=activeItems();const ready=state.orders.filter(o=>orderStatus(state,o)==='ready');return pageHeading('A good service starts here.','A clear view of your floor, your orders, and the details that matter.',btn(icon('spark')+' Sample scenarios','scenarios','secondary')+(canEditOrder()?btn(icon('plus')+' New order','new-order','primary'):''),'YOUR SERVICE, AT A GLANCE')+demoNotice()+`<section class="stats" aria-label="Service metrics">${stat('Occupied tables',`${occupied.length}<span style="font-size:16px;font-weight:400;color:#a3ad98"> / ${state.tables.length}</span>`,'table','Across the restaurant')}${stat('Active orders',state.orders.filter(o=>o.items.some(i=>!['served','canceled'].includes(i.status))).length,'orders','Keeping service moving')}${stat('Dietary reviews',findings().length,'shield','Dishes that need attention',true)}${stat('Ready to serve',ready.length,'kitchen','Fresh from the kitchen')}</section><div class="work-grid"><div><div class="section-heading"><div><h2>Your floor</h2><p>A place for every guest. A clear status for every table.</p></div><div class="segmented">${['All tables','Occupied'].map(x=>`<button data-action="floor-filter" data-value="${x}" class="${x===tableFilter?'active':''}">${x}</button>`).join('')}</div></div><div class="table-grid">${state.tables.filter(t=>tableFilter==='All tables'||occupied.includes(t)).map(tableCard).join('')}</div><section class="recent"><div class="section-heading"><h2>Recent orders</h2><button class="section-link" data-action="nav" data-page="orders">View all orders ${icon('arrow')}</button></div>${ordersTable(state.orders.slice(0,4))}</section></div><aside class="rail"><section class="rail-card"><div class="rail-title"><h3>Needs a closer look</h3><span class="badge amber">${findings().length} pending</span></div>${findings().slice(0,3).map(({o,i})=>`<div class="review-preview"><div class="review-head"><span>${esc(table(o.table)?.name)} <span class="muted">· #${o.id}</span></span>${icon('alert')}</div><p class="dish-name">${esc(dish(i.dish)?.name)}</p><span class="badge ${check(state,o,i)[0].type}">${esc(check(state,o,i)[0].type==='direct'?'Direct match':check(state,o,i)[0].type==='potential'?'Cross-contact risk':'Information pending')}</span><p>${esc(check(state,o,i)[0].diner)} · ${esc(check(state,o,i)[0].restriction)}</p>${btn('View review '+icon('arrow'),'item-detail','sm',`data-order="${o.id}" data-item="${i.id}"`)}</div>`).join('')||'<div class="review-preview"><p>No pending dietary findings.</p></div>'}</section><section class="care-card">${icon('leaf','watermark')}<div class="eyebrow">THOUGHTFUL BY DESIGN</div><h3>Good food.<br>A little more care.</h3><p>Small details make a big difference. Keep declarations current and bring the kitchen into the conversation.</p>${btn('Explore the menu '+icon('arrow'),'nav','text sm','data-page="menu" style="padding-left:0;margin-top:10px"')}</section></aside></div>`;}
function tableCard(t){const os=liveOrders(t),a=os.flatMap(o=>o.items.filter(i=>!['served','canceled'].includes(i.status)&&blocked(state,o,i))),status=a.length?'Needs review':os.some(o=>orderStatus(state,o)==='ready')?'Ready to serve':os.some(o=>orderStatus(state,o)==='in preparation')?'In preparation':os.length?'Order received':t.diners.length?'Taking orders':'Available';return`<button class="table-card ${!t.diners.length&&!os.length?'empty':''} ${a.length?'alert-table':''}" data-action="table" data-id="${t.id}"><div class="table-top"><strong>${esc(t.name)}</strong><span class="badge ${a.length?'amber':status==='Ready to serve'?'green':status==='In preparation'?'blue':'gray'}">${a.length?icon('alert'):''}${status}</span></div><div class="table-meta"><span>${icon('users')} ${t.diners.length||t.capacity} ${t.diners.length?'diners':'seats'}</span><span>${icon('clock')} ${os.length?elapsed(os[0].created)+' min':t.zone}</span></div><div class="table-bottom">${a.length?`<span class="table-label">${icon('shield')}${a.length} dietary review${a.length===1?'':'s'}</span>`:os.length?`<span>${os.reduce((n,o)=>n+o.items.filter(i=>i.status!=='canceled').length,0)} dishes ordered</span>`:`<span>${t.diners.length?'Add a dish to get started':'Open table'}</span>`}<span class="table-money">${os.length?money(os.reduce((n,o)=>n+total(o),0)):icon('plus')}</span></div></button>`;}
function ordersTable(list){return`<div class="table-wrap"><table class="data-table"><thead><tr><th>ORDER</th><th>TABLE</th><th>DINERS</th><th>STATUS</th><th>REVIEW</th><th>TOTAL</th><th></th></tr></thead><tbody>${list.map(o=>`<tr><td><button class="row-link" data-action="table" data-id="${o.table}">#${o.id}</button></td><td>${esc(table(o.table)?.name)}</td><td>${new Set(o.items.flatMap(i=>i.diners)).size} ${new Set(o.items.flatMap(i=>i.diners)).size===1?'diner':'diners'}</td><td>${statusBadge(orderStatus(state,o))}</td><td>${o.items.some(i=>!['served','canceled'].includes(i.status)&&blocked(state,o,i))?'<span class="badge amber">'+icon('shield')+' Review needed</span>':'<span class="badge green">'+icon('check')+' No pending findings</span>'}</td><td>${money(total(o))}</td><td><button class="icon-btn" aria-label="Open order ${o.id}" data-action="table" data-id="${o.table}">${icon('arrow')}</button></td></tr>`).join('')||'<tr><td colspan="7">No orders in this view.</td></tr>'}</tbody></table></div>`;}
function menuPage(){const list=state.dishes.filter(d=>(menuCategory==='All dishes'||d.category===menuCategory)&&(d.name+' '+d.description).toLowerCase().includes(menuSearch.toLowerCase()));return pageHeading('The menu','Every ingredient has a story. Know what goes on every plate.',role==='Administration'?btn(icon('plus')+' New dish','edit-dish','primary'):btn(icon('spark')+' Sample scenarios','scenarios'))+demoNotice()+`<div class="toolbar"><div class="tabs">${['All dishes',...state.settings.categories].map(c=>`<button class="${menuCategory===c?'active':''}" data-action="category" data-value="${esc(c)}">${esc(c)}${c==='All dishes'?` <span class="muted">${state.dishes.length}</span>`:''}</button>`).join('')}</div><label class="search">${icon('search')}<input id="menu-search" placeholder="Find a dish…" aria-label="Search menu" value="${esc(menuSearch)}"></label></div><div class="menu-grid">${list.map(d=>{const nodes=composition(state,d);const names=[...new Set(nodes.flatMap(n=>n.contains||[]))].map(id=>state.allergens.find(a=>a.id===id)?.name||id);return`<article class="dish-card"><div class="dish-image"><img src="${esc(d.image)}" alt="Illustrative ${esc(d.name)}" loading="lazy"><span class="badge ${d.status==='available'?'green':'gray'}">${d.status==='available'?'<span class="dot"></span>':icon('x')}${esc(d.status[0].toUpperCase()+d.status.slice(1))}</span></div><div class="dish-content"><div class="dish-title"><h3>${esc(d.name)}</h3><span class="price">${money(d.price)}</span></div><p>${esc(d.description)}</p><div class="allergen-pills">${names.map(n=>`<span>Contains: ${esc(n)}</span>`).join('')}${nodes.some(n=>n.unknown)?'<span>⚠ Information pending</span>':''}${!names.length?'<span>View full composition & risks</span>':''}</div><div class="dish-controls">${btn(icon('book')+' Ingredients','dish-detail','text sm',`data-id="${d.id}"`)}${canEditOrder()?btn(icon('plus')+' Add to order','add-dish','primary sm',`data-id="${d.id}" ${d.status!=='available'?'disabled':''}`):''}</div></div></article>`;}).join('')||'<div class="empty-state">No dishes match your search.</div>'}</div>`;}
function ordersPage(){const list=state.orders.filter(o=>orderFilter==='All'||(orderFilter==='Needs review'?o.items.some(i=>!['served','canceled'].includes(i.status)&&blocked(state,o,i)):orderStatus(state,o)===orderFilter.toLowerCase()));return pageHeading('Orders, in good hands.','Follow each plate from the first request to the final handoff.',canEditOrder()?btn(icon('plus')+' New order','new-order','primary'):'')+demoNotice()+`<div class="toolbar"><div class="tabs">${['All','Needs review','In preparation','Ready','Served'].map(x=>`<button class="${orderFilter===x?'active':''}" data-action="order-filter" data-value="${x}">${x}</button>`).join('')}</div><span class="help-text">${list.length} orders · Changes save automatically</span></div>${ordersTable(list)}`;}
function dinerCard(d,t){return`<div class="diner-card"><div class="diner-head"><strong>${icon('users')} ${esc(d.name)}</strong>${canEditOrder()?btn(icon('edit'),'edit-diner','text sm',`data-table="${t.id}" data-id="${d.id}" aria-label="Edit ${esc(d.name)} restrictions"`):''}</div>${d.state==='none'?'<span class="badge green">'+icon('check')+' No restrictions declared</span>':d.state==='notAsked'?'<span class="badge amber">'+icon('alert')+' Not yet asked</span>':d.restrictions.map(r=>`<span class="restriction-pill">${esc(labelRestriction(r))}</span>`).join('')}${d.notes?`<p>Manual review: ${esc(d.notes)}</p>`:''}</div>`;}
function tablePage(){const t=table(selectedTable);if(!t)return'<div class="empty-state">Table not found.</div>';const os=state.orders.filter(o=>o.table===t.id);return pageHeading(esc(t.name),`${t.zone} · ${t.diners.length} ${t.diners.length===1?'diner':'diners'} · Session ${t.session.slice(-6)}`,btn(icon('arrow')+' All tables','nav','','data-page="dashboard"')+(canEditOrder()?btn(icon('plus')+' Add a dish','table-menu','primary',`data-id="${t.id}"`):''))+demoNotice()+`<div class="editor-grid"><aside><section class="panel"><div class="section-heading"><h3 style="margin:0">Your diners</h3>${canEditOrder()?btn(icon('plus'),'add-diner','sm',`data-table="${t.id}" aria-label="Add diner"`):''}</div><p class="help-text mb">Ask every diner. A missing declaration is never treated as no restrictions.</p><div class="diners">${t.diners.map(d=>dinerCard(d,t)).join('')||'<p class="help-text">Add a diner to start this table.</p>'}</div></section><div class="callout mt">${icon('shield')} <strong>Every plate, individually checked.</strong><p class="help-text">Shared dishes are checked for everyone selected. Kitchen reviews never remove unresolved findings.</p></div>${os.find(o=>['late','recipe'].includes(o.scenario))?`<div class="panel mt"><h3>Try the next step</h3><p class="help-text mb">${os.find(o=>o.scenario==='late')?'Add an olive oil ingredient allergy. The original review will become invalid.':'Switch to Administration, then change the lemon ingredient to contain milk. The original review will become invalid.'}</p>${btn('Apply scenario change','scenario-change','primary',`data-order="${os.find(o=>['late','recipe'].includes(o.scenario)).id}"`)}</div>`:''}</aside><div>${os.map(o=>`<section class="panel mb"><div class="section-heading"><div><h3 style="margin:0">Order #${o.id}</h3><p>${fmt(o.created)} · ${elapsed(o.created)} min ago</p></div>${statusBadge(orderStatus(state,o))}</div>${o.items.map(i=>orderItemHTML(o,i)).join('')||'<p class="help-text">This order is empty. Add a dish from the menu.</p>'}<div class="order-footer"><div><span class="help-text">Order total</span><br><strong>${money(total(o))}</strong></div><div class="actions">${canEditOrder()?btn(icon('plus')+' Add dish','table-menu','',`data-id="${t.id}"`):''}${canEditOrder()&&o.items.some(i=>!i.submitted&&i.status!=='canceled')?btn('Review & send '+icon('arrow'),'send-summary','primary',`data-order="${o.id}"`):''}</div></div></section>`).join('')||`<div class="empty-state">${icon('orders')}<h3>A fresh start for this table</h3><p>Register diners, record declarations, then choose something from the menu.</p>${canEditOrder()?btn('Browse the menu '+icon('arrow'),'table-menu','primary',`data-id="${t.id}"`):''}</div>`}</div></div>`;}
function orderItemHTML(o,i,kitchen=false){const d=dish(i.dish),t=table(o.table),a=check(state,o,i),names=i.diners.map(id=>t.diners.find(x=>x.id===id)?.name||'Missing diner');const reviews=i.reviews||[];return`<article class="order-item"><div class="item-top"><div><strong>${i.quantity} × ${esc(d?.name||'Archived dish')}</strong><div class="item-meta">${names.length>1?'Shared · ':''}${esc(names.join(' + '))}${i.mod?' · '+esc(d?.modifications.find(m=>m.id===i.mod)?.name||'Unreviewed variant'):''}</div></div>${statusBadge(i.status)}</div>${i.notes?`<p class="help-text">Kitchen note: ${esc(i.notes)}</p>`:''}${kitchen?i.diners.map(id=>t.diners.find(x=>x.id===id)).filter(Boolean).map(di=>di.restrictions.length?`<p class="help-text"><strong>${esc(di.name)}:</strong> ${di.restrictions.map(r=>esc(labelRestriction(r))).join(' · ')}</p>`:'').join(''):''}${!['canceled','served'].includes(i.status)?checksHTML(o,i,kitchen?2:3):'<p class="help-text">Historical item · recipe and findings retained in its snapshots.</p>'}${reviews.some(r=>r.invalidated||r.fingerprint!==fingerprint(state,o,i))?'<div class="warning-box">'+icon('history')+' A previous review is invalid. Relevant information changed; a new kitchen review is required.</div>':''}${reviews.filter(r=>!r.invalidated&&r.fingerprint===fingerprint(state,o,i)).length?`<p class="help-text mt">${icon('check')} Review recorded · ${esc(reviews.at(-1).author)}. ${a.length?'Unresolved findings still block preparation.':''}</p>`:''}<div class="item-controls">${btn(icon('eye')+' Details','item-detail','sm',`data-order="${o.id}" data-item="${i.id}"`)}${canEditOrder()&&!['canceled','served'].includes(i.status)?btn(icon('edit')+' Modify','edit-item','sm',`data-order="${o.id}" data-item="${i.id}"`):''}${a.length&&!['canceled','served'].includes(i.status)?btn(i.requested?'Review requested':icon('shield')+' Request review','request-review','sm',`data-order="${o.id}" data-item="${i.id}" ${i.requested?'disabled':''}`):''}${kitchen&&role!=='Waitstaff'?kitchenControls(o,i):''}${canEditOrder()&&!i.submitted&&i.status!=='canceled'?btn(icon('trash'),'remove-item','danger sm',`data-order="${o.id}" data-item="${i.id}" aria-label="Remove dish"`):''}</div></article>`;}
function kitchenControls(o,i){if(!i.submitted)return'';return(!['canceled','served'].includes(i.status)?btn('Record review','review-item','sm',`data-order="${o.id}" data-item="${i.id}"`):'')+({'received':btn('Start preparation','transition','primary sm',`data-order="${o.id}" data-item="${i.id}" data-next="in preparation" ${blocked(state,o,i)?'disabled':''}`),'in preparation':btn('Mark ready','transition','primary sm',`data-order="${o.id}" data-item="${i.id}" data-next="ready" ${blocked(state,o,i)?'disabled':''}`),ready:btn('Mark served','transition','primary sm',`data-order="${o.id}" data-item="${i.id}" data-next="served" ${blocked(state,o,i)?'disabled':''}`)}[i.status]||'');}
function kitchenPage(){const list=state.orders.filter(o=>o.items.some(i=>i.submitted&&(kitchenFilter==='All'||!['served','canceled'].includes(i.status))));return pageHeading('From our kitchen, with care.','One ticket. Every diner. All the details your team needs.',btn(icon('history')+' Review history','review-history'))+demoNotice()+`<div class="toolbar"><div class="tabs">${['Active','All'].map(x=>`<button data-action="kitchen-filter" data-value="${x}" class="${kitchenFilter===x?'active':''}">${x==='All'?'Including completed':'Active tickets'}</button>`).join('')}</div><p class="help-text">${role==='Waitstaff'?'Read-only in Waitstaff mode. Select Kitchen to record reviews and update preparation.':'Blocked plates cannot enter preparation. Other dishes can proceed.'}</p></div><div class="kitchen-grid">${list.map(o=>`<section class="ticket ${o.items.some(i=>blocked(state,o,i))?'has-warning':''}"><header class="ticket-head"><div><h2>${esc(table(o.table)?.name)}</h2><p>#${o.id} · Arrived ${new Date(o.created).toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'})} · ${elapsed(o.created)} min</p></div>${statusBadge(orderStatus(state,o))}</header><div class="ticket-body">${o.items.filter(i=>i.submitted).sort((a,b)=>a.diners.join().localeCompare(b.diners.join())).map(i=>orderItemHTML(o,i,true)).join('')}</div></section>`).join('')||'<div class="empty-state">No kitchen tickets yet.</div>'}</div>`;}
function reviewsPage(){return pageHeading('A closer look. A clearer decision.','Keep the diner, the recipe and the kitchen on the same page.',btn(icon('history')+' Review history','review-history'))+demoNotice()+`<div class="callout mb"><strong>${findings().length} dishes have unresolved findings.</strong> A review records the kitchen’s assessment. A plate remains blocked until the underlying composition or information is corrected and checks find no unresolved issue.</div><div class="review-list">${findings().map(({o,i})=>`<article class="review-card"><div class="review-card-top"><div><h3>${esc(dish(i.dish)?.name)}</h3><p>${esc(table(o.table)?.name)} · Order #${o.id} · ${i.quantity} plate${i.quantity===1?'':'s'} · ${i.mod?esc(dish(i.dish)?.modifications.find(m=>m.id===i.mod)?.name):'Standard recipe'}</p></div><span class="badge amber">${icon('shield')} Preparation blocked</span></div><div class="alert-lines">${checksHTML(o,i)}</div><div class="actions">${btn('View ingredients','item-detail','',`data-order="${o.id}" data-item="${i.id}"`)}${canEditOrder()?btn('Choose an alternative','alternative','',`data-order="${o.id}" data-item="${i.id}"`):''}${btn(i.requested?'Review requested':'Request kitchen review','request-review','',`data-order="${o.id}" data-item="${i.id}" ${i.requested?'disabled':''}`)}${role!=='Waitstaff'?btn('Record kitchen review','review-item','primary',`data-order="${o.id}" data-item="${i.id}"`):''}${canEditOrder()&&!i.submitted?btn('Remove dish','remove-item','danger',`data-order="${o.id}" data-item="${i.id}"`):''}</div></article>`).join('')||`<div class="empty-state">${icon('shield')}<h3>No pending findings</h3><p>No matches were found in the current information. Continue to follow restaurant procedures.</p></div>`}</div>`;}
function adminPage(){return pageHeading('Keep the details up to date.','One source of information, from the supplier to the service.',btn(icon('download')+' Export demo data','export-data'))+demoNotice()+`<nav class="admin-tabs" aria-label="Administration sections">${['Menu','Ingredients','Allergens','Cross-contact','Users','History','Settings'].map(x=>`<button data-action="admin-tab" data-value="${x}" class="${adminTab===x?'active':''}">${x==='Ingredients'?'Ingredients & recipes':x==='Users'?'Users & permissions':x}</button>`).join('')}</nav>${adminContent()}`;}
function adminTable(headers,rows){return`<div class="table-wrap"><table class="data-table"><thead><tr>${headers.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`;}
function adminContent(){if(adminTab==='Menu')return`<div class="section-heading"><div><h2>Menu management</h2><p>${state.dishes.length} dishes · Recipe allergens are calculated from ingredients</p></div>${btn(icon('plus')+' Create dish','edit-dish','primary')}</div>${adminTable(['DISH','CATEGORY','PRICE','AVAILABILITY','RECIPE','ACTIONS'],state.dishes.map(d=>`<tr><td>${esc(d.name)}</td><td>${esc(d.category)}</td><td>${money(d.price)}</td><td>${esc(d.status)}</td><td>v${d.version} · ${d.verified?'Reviewed':'Pending'}</td><td><div class="actions">${btn('Edit','edit-dish','sm',`data-id="${d.id}"`)}${btn(icon('copy'),'duplicate-dish','sm',`data-id="${d.id}" aria-label="Duplicate ${esc(d.name)}"`)}${btn(d.status==='deactivated'?'Activate':'Deactivate','toggle-dish','sm',`data-id="${d.id}"`)}</div></td></tr>`))}`;
if(adminTab==='Ingredients')return`<div class="section-heading"><div><h2>Ingredients & subingredients</h2><p>Review the affected dishes before saving a composition change.</p></div>${btn(icon('plus')+' Add ingredient','edit-ingredient','primary')}</div>${adminTable(['INGREDIENT','CONTAINS','SUBINGREDIENTS','REVIEW','ACTIONS'],state.ingredients.map(i=>`<tr><td>${esc(i.name)}<br><small class="muted">${esc(i.supplier)}</small></td><td>${i.contains.map(id=>esc(state.allergens.find(a=>a.id===id)?.name||id)).join(', ')||'None recorded'}</td><td>${i.subs.map(id=>esc(state.ingredients.find(a=>a.id===id)?.name||id)).join(', ')||'Single ingredient'}</td><td><span class="badge ${i.verified?'green':'amber'}">${i.verified?'Reviewed':'Awaiting verification'}</span></td><td>${btn('Edit & impact','edit-ingredient','sm',`data-id="${i.id}"`)}</td></tr>`))}`;
if(adminTab==='Allergens')return`<div class="section-heading"><div><h2>Allergens & restrictions</h2><p>Stable identifiers drive checks. Archiving preserves all references and historical warnings.</p></div>${btn(icon('plus')+' Add allergen','edit-allergen','primary')}</div>${adminTable(['NAME','ALTERNATIVE NAMES','STATUS','ACTIONS'],state.allergens.map(a=>`<tr><td>${esc(a.name)}</td><td>${esc(a.aliases)||'—'}</td><td>${a.active?'Active':'Archived · still checked'}</td><td><div class="actions">${btn('Edit','edit-allergen','sm',`data-id="${a.id}"`)}${btn(a.active?'Archive':'Restore','archive-allergen','sm',`data-id="${a.id}"`)}</div></td></tr>`))}<div class="callout mt">Ingredient-specific restrictions use the ingredient catalog. Allergy, intolerance and other dietary restrictions are recorded separately on each diner. Vegan and lactose-free labels are never treated as allergen guarantees.</div>`;
if(adminTab==='Cross-contact')return`<div class="section-heading"><div><h2>Preparation areas & equipment</h2><p>Equipment risks persist when an ingredient is removed.</p></div>${btn(icon('plus')+' Add area','edit-area','primary')}</div><div class="menu-grid">${state.areas.map(a=>`<section class="panel"><h3>${esc(a.name)}</h3><span class="badge ${a.verified?'green':'amber'}">${a.verified?'Information reviewed':'Awaiting verification'}</span><p class="help-text mt">Possible cross-contact: ${a.allergens.map(id=>esc(state.allergens.find(x=>x.id===id)?.name||id)).join(', ')||'None recorded'}</p><p class="help-text mb">${esc(a.notes)}</p>${btn('Edit risks & procedure','edit-area','',`data-id="${a.id}"`)}</section>`).join('')}</div><p class="help-text mt">Ingredient-level risks are editable under Ingredients. Dish-level risks and linked equipment are editable in each recipe.</p>`;
if(adminTab==='Users')return`<div class="section-heading"><div><h2>Demonstration profiles</h2><p>These profiles simulate permissions in this browser. They are not authenticated accounts.</p></div>${btn(icon('plus')+' Add profile','edit-user','primary')}</div>${adminTable(['PROFILE','ROLE','ACCESS','ACTIONS'],state.users.map(u=>`<tr><td>${esc(u.name)}</td><td>${esc(u.role)}</td><td>${u.active?'Enabled':'Disabled'}</td><td>${btn('Edit profile','edit-user','sm',`data-id="${u.id}"`)}</td></tr>`))}<div class="two-panels mt"><div class="panel"><h3>Permission definitions</h3><p class="help-text"><strong>Waitstaff:</strong> tables, diners, orders, review requests.<br><strong>Kitchen:</strong> composition review, review outcomes, preparation transitions.<br><strong>Administration:</strong> all demonstration actions, recipe editing, catalogs, profiles and settings.</p></div><div class="callout">Production requires server-side authentication, authorization and validation of all status transitions. Local role switching is only a way to evaluate these workflows.</div></div>`;
if(adminTab==='History')return`<div class="section-heading"><div><h2>A record of every relevant change</h2><p>Author, timestamp, previous values and updated values are retained locally.</p></div>${btn('Order snapshots','snapshots')}</div><section class="panel"><div class="timeline">${state.history.map(h=>`<article class="history-entry"><h4>${esc(h.action)} · ${esc(h.entity)}</h4><p>${esc(h.author)} · ${fmt(h.at)}</p><details><summary>Compare previous and new values</summary><div class="field-row"><div><span>Previous</span><pre>${esc(JSON.stringify(h.before,null,2))}</pre></div><div><span>Updated</span><pre>${esc(JSON.stringify(h.after,null,2))}</pre></div></div></details></article>`).join('')}</div></section>`;
return`<div class="two-panels"><section class="panel"><h3>Restaurant & service</h3><form id="settings-form"><div class="field"><label for="restaurant">Restaurant name</label><input id="restaurant" name="restaurant" value="${esc(state.settings.restaurant)}" required></div><div class="field"><label for="service">Service label</label><input id="service" name="service" value="${esc(state.settings.service)}" required></div><div class="field"><label for="categories">Menu categories (comma separated)</label><input id="categories" name="categories" value="${esc(state.settings.categories.join(', '))}" required><small>Existing dish categories are preserved when they are in use.</small></div><div class="field"><label for="procedure">Internal review procedure</label><textarea id="procedure" name="procedure" required>${esc(state.settings.procedure)}</textarea></div><button class="button primary" type="submit">Save settings</button></form></section><div><section class="panel"><div class="section-heading"><h3 style="margin:0">Tables & floor</h3>${btn(icon('plus')+' Add table','edit-table','sm')}</div>${state.tables.map(t=>`<div class="summary-row"><span>${esc(t.name)} · ${t.capacity} seats</span>${btn('Edit','edit-table','text sm',`data-id="${t.id}"`)}</div>`).join('')}</section><section class="panel mt"><h3>Preparation statuses</h3><form id="status-form">${state.settings.statuses.map(x=>field('status-'+x,esc(x[0].toUpperCase()+x.slice(1)),state.settings.statusLabels?.[x]||x[0].toUpperCase()+x.slice(1))).join('')}<p class="help-text mb">Customize display labels. Stable status identifiers and blocking rules are preserved. Dietary review status is tracked separately.</p><button class="button primary" type="submit">Save status labels</button></form></section><section class="panel mt"><h3>Reset the demonstration</h3><p class="help-text mb">Clear diner information, orders, notes, reviews and change history, then restore fictional sample data.</p>${btn(icon('history')+' Reset demo & clear diner data','reset-confirm','danger')}</section></div></div>`;
}
function field(name,label,value='',type='text',hint=''){return`<div class="field"><label for="f-${name}">${label}</label><input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${['name','price'].includes(name)?'required':''} ${type==='number'?'min="0" step="0.01"':''}>${hint?`<small>${hint}</small>`:''}</div>`;}
function selectField(name,label,options,value){return`<div class="field"><label for="f-${name}">${label}</label><select id="f-${name}" name="${name}">${options.map(o=>{const[v,l]=Array.isArray(o)?o:[o,o];return`<option value="${esc(v)}" ${value===v?'selected':''}>${esc(l)}</option>`;}).join('')}</select></div>`;}
function textField(name,label,value='',hint=''){return`<div class="field"><label for="f-${name}">${label}</label><textarea id="f-${name}" name="${name}">${esc(value)}</textarea>${hint?`<small>${hint}</small>`:''}</div>`;}
function checksField(name,label,list,selected=[],hint=''){return`<div class="field"><span class="field-label">${label}</span><div class="check-list">${list.map(x=>`<label class="check"><input type="checkbox" name="${name}" value="${esc(x.id)}" ${selected.includes(x.id)?'checked':''}>${esc(x.name)}</label>`).join('')||'<span class="help-text">No entries configured.</span>'}</div>${hint?`<small>${hint}</small>`:''}</div>`;}
const verifiedField=v=>selectField('verified','Information review status',[['true','Reviewed · fictional data only'],['false','Awaiting verification']],String(v));
function formModal(title,sub,body,onSubmit,{wide=false,label='Save changes'}={}){modal(title,sub,`<form id="modal-form">${body}</form>`,btn('Cancel','close')+`<button type="submit" form="modal-form" class="button primary">${label}</button>`,wide);$('#modal-form').addEventListener('submit',e=>{e.preventDefault();onSubmit(new FormData(e.currentTarget),e.currentTarget);});}
function newOrder(){const t=table(selectedTable)||state.tables[0];formModal('Start with a table','Diners can be added before you choose dishes.',selectField('table','Table',state.tables.map(t=>[t.id,`${t.name} · ${t.diners.length} diners · ${t.zone}`]),t.id)+field('count','Diners to add',t.diners.length?0:2,'number','New diners begin with “Not yet asked”.'),fd=>{let target;mutate(()=>{allow(role,'table');target=table(fd.get('table'));const count=+fd.get('count');if(!Number.isInteger(count)||count<0||count>20)throw Error('Choose 0–20 diners.');for(let n=0;n<count;n++)target.diners.push({id:uid('diner'),name:`Diner ${target.diners.length+1}`,state:'notAsked',restrictions:[],notes:''});audit(state,role,'Service table opened',target.name,null,target);},'Table ready. Record a declaration for every diner.');if(target)nav('table',target.id);},{label:'Open table'});}
function editDiner(tid,id){allow(role,'diner');const t=table(tid),prev=t.diners.find(d=>d.id===id),d=prev||{id:uid('diner'),name:`Diner ${t.diners.length+1}`,state:'notAsked',restrictions:[],notes:''};
let restrictions=clone(d.restrictions);const body=field('name','Diner identifier',d.name,'text','Use a simple identifier. No full names are needed.')+selectField('state','Declaration status',[['notAsked','Not yet asked'],['none','No restrictions declared'],['declared','Restrictions declared']],d.state)+`<div id="restriction-list"></div><div class="field-row">${selectField('restrictionType','Restriction type',['allergy','intolerance','other'],'allergy')}${selectField('target','Catalog',[['allergen','Allergens'],['ingredient','Specific ingredients']],'allergen')}</div><div class="field"><label for="restriction-catalog">Structured restriction</label><select id="restriction-catalog"></select></div>${btn(icon('plus')+' Add structured restriction','add-restriction','sm')}<hr class="subtle-line">${textField('notes','Free-text declaration / manual review',d.notes,'Free text is not automatically matched. Any free-text declaration requires manual review and blocks the plate until clarified in structured information.')}<div class="callout">Changing a declaration rechecks every active dish for this diner, including shared dishes, and invalidates relevant previous reviews.</div>`;
formModal(prev?'Diner details':'Add a diner',`${esc(t.name)} · Every declaration belongs to one diner.`,body,fd=>mutate(()=>{allow(role,'diner');const v={...d,name:String(fd.get('name')).trim(),state:fd.get('state'),restrictions:fd.get('state')==='declared'?restrictions:[],notes:String(fd.get('notes')).trim()};if(!v.name)throw Error('Diner identifier is required.');if(v.state==='none'&&(restrictions.length||v.notes))throw Error('Remove restrictions and free text before declaring no restrictions.');if(v.state==='declared'&&!v.restrictions.length&&!v.notes)throw Error('Record a structured restriction or a free-text declaration.');if(prev)t.diners[t.diners.indexOf(prev)]=v;else t.diners.push(v);audit(state,role,'Diner declaration updated',`${t.name} / ${v.name}`,prev,v);},'Declaration saved. All affected dishes have been checked again.'));
const list=()=>{$('#restriction-list').innerHTML=restrictions.length?`<div class="mb">${restrictions.map((r,i)=>`<div class="summary-row"><span>${esc(labelRestriction(r))}</span><button type="button" class="icon-btn" data-remove-restriction="${i}" aria-label="Remove restriction">${icon('x')}</button></div>`).join('')}</div>`:'';$('#restriction-list').querySelectorAll('[data-remove-restriction]').forEach(b=>b.onclick=()=>{restrictions.splice(+b.dataset.removeRestriction,1);list();});};
const cat=()=>{$('#restriction-catalog').innerHTML=( $('[name="target"]').value==='allergen'?state.allergens.filter(a=>a.active):state.ingredients).map(x=>`<option value="${x.id}">${esc(x.name)}${x.aliases?' · '+esc(x.aliases):''}</option>`).join('');};$('[name="target"]').onchange=cat;cat();list();$('[data-action="add-restriction"]').onclick=()=>{const r={type:$('[name="restrictionType"]').value,target:$('[name="target"]').value,id:$('#restriction-catalog').value};if(!restrictions.some(x=>JSON.stringify(x)===JSON.stringify(r)))restrictions.push(r);$('[name="state"]').value='declared';list();};
}
function dishDetail(id,o,i){const d=dish(id);if(!d)return;const nodes=composition(state,d,i?.mod);modal(esc(d.name),`${esc(d.category)} · ${money(d.price)} · Recipe v${d.version} · Updated ${esc(d.reviewDate)}`,`<img class="modal-image" src="${esc(d.image)}" alt="Illustrative ${esc(d.name)}"><div class="dish-detail-head"><p class="help-text">${esc(d.description)}</p><span class="badge ${d.verified?'green':'amber'}">${d.verified?'Information reviewed':'Review pending'}</span></div>${o&&i?`<h3 class="mt">${esc(table(o.table)?.name)} · ${i.diners.map(id=>esc(table(o.table)?.diners.find(d=>d.id===id)?.name||id)).join(' + ')}</h3><p class="help-text">Variant: ${esc(d.modifications.find(m=>m.id===i.mod)?.name||'Standard recipe')}</p>${checksHTML(o,i)}`:''}<h3 class="mt">Complete ingredient relationships</h3><p class="help-text">Contains, may contain and cross-contact information are separate.</p><div class="recipe-tree">${nodes.map(n=>`<div class="recipe-node" style="padding-left:${Math.max(0,n.path.length-2)*17}px"><span>${n.path.length>2?'↳ ':''}${esc(n.name)}</span>${['contains','may','cross'].map(prop=>(n[prop]||[]).map(a=>`<span class="badge ${prop==='contains'?'gray':'amber'}">${prop==='contains'?'Contains':prop==='may'?'May contain':'Cross-contact'}: ${esc(state.allergens.find(x=>x.id===a)?.name||a)}</span>`).join('')).join('')}${n.unknown?'<span class="badge amber">Awaiting verification</span>':''}<small>${esc(d.recipe.find(r=>r.ingredient===n.id)?.quantity||'')}</small></div>`).join('')}</div><h3 class="mt">Preparation & cross-contact</h3>${d.areas.map(id=>state.areas.find(a=>a.id===id)).filter(Boolean).map(a=>`<div class="warning-box">${icon('alert')}<div><strong>${esc(a.name)} · ${a.verified?'Reviewed information':'Awaiting verification'}</strong>${esc(a.notes)}<br>Associated allergens: ${a.allergens.map(id=>esc(state.allergens.find(x=>x.id===id)?.name||id)).join(', ')||'None recorded'}</div></div>`).join('')||'<p class="help-text mt">No equipment risk recorded. This is not a guarantee that cross-contact is absent.</p>'}${d.cross.length?`<div class="warning-box">Dish-level possible cross-contact: ${d.cross.map(id=>esc(state.allergens.find(a=>a.id===id)?.name||id)).join(', ')}</div>`:''}${o&&i?`<h3 class="mt">Review record</h3>${i.reviews.map(r=>`<div class="history-entry"><h4>${esc(r.outcome)} ${r.invalidated||r.fingerprint!==fingerprint(state,o,i)?'<span class="badge amber">Invalidated</span>':''}</h4><p>${esc(r.author)} · ${fmt(r.at)}</p><p>${esc(r.notes)}</p></div>`).join('')||'<p class="help-text mt">No kitchen review recorded.</p>'}<p class="help-text mt">${i.snapshots.length} composition snapshot(s) retained for this item.</p>`:''}<div class="callout mt">Illustrative and unvalidated information. Food labels and no-match results do not guarantee suitability. Follow restaurant procedures.</div>`,btn('Close','close')+(canEditOrder()&&d.status==='available'&&!o?btn(icon('plus')+' Add to order','add-dish','primary',`data-id="${d.id}"`):''),true);}
function addDish(id,existingOrder=null,existingItem=null){allow(role,'order');const d=dish(id);if(d.status!=='available')return toast('This dish is not currently available.',true);const defaultTable=table(existingOrder?.table||selectedTable)||state.tables[0];
const body=selectField('table','Assign to table',state.tables.map(t=>[t.id,`${t.name} · ${t.diners.length} diners`]),defaultTable.id)+`<div id="participants"></div><div class="field-row">${field('quantity','Quantity',existingItem?.quantity||1,'number')}${selectField('mod','Reviewed recipe variant',[['','Standard recipe'],...d.modifications.filter(m=>m.reviewed).map(m=>[m.id,m.name])],existingItem?.mod||'')}</div>${textField('notes','Kitchen notes',existingItem?.notes||'','Notes communicate requests. They do not change recipe composition or clear an alert.')}<h3 class="mt">Live dietary check</h3><div id="live-check"></div>`;
const preview=()=>{const t=table($('[name="table"]').value);const ids=[...document.querySelectorAll('[name="participants"]:checked')].map(e=>e.value);return{t,o:existingOrder||{table:t.id,id:'draft'},i:{id:existingItem?.id||'preview',dish:d.id,diners:ids,quantity:+$('[name="quantity"]').value,mod:$('[name="mod"]').value,notes:$('[name="notes"]').value}};};
formModal(existingItem?'Modify the dish':'Add a little something',`${esc(d.name)} · ${money(d.price)} · Shared dishes are checked for every participant.`,body,fd=>{const p=preview();mutate(()=>{allow(role,'order');if(!p.i.diners.length)throw Error('Select at least one diner.');if(!Number.isInteger(p.i.quantity)||p.i.quantity<1||p.i.quantity>50)throw Error('Quantity must be 1–50.');if(existingItem&&['served','canceled','ready','in preparation'].includes(existingItem.status))throw Error('This dish can no longer be modified. Cancel it through the kitchen review workflow and create another dish.');let o=existingOrder;if(!o){o=liveOrders(p.t).find(o=>o.items.some(i=>!i.submitted))||{id:String(Math.max(1043,...state.orders.map(x=>+x.id))+1),table:p.t.id,created:new Date().toISOString(),items:[]};if(!state.orders.includes(o))state.orders.unshift(o);}if(existingItem){const before=clone(existingItem);Object.assign(existingItem,p.i);audit(state,role,'Order dish modified',`#${o.id}`,before,existingItem);}else{const i={...p.i,id:uid('item'),status:'draft',submitted:false,requested:false,reviews:[],snapshots:[]};o.items.push(i);audit(state,role,'Dish added to order',`#${o.id}`,null,i);}selectedTable=p.t.id;},existingItem?'Dish updated and checked again.':'Dish added. Review its findings before sending.');if(!$('#modal-form'))nav('table',selectedTable);},{label:existingItem?'Save & recheck':'Add to order'});
if(existingOrder)$('[name="table"]').disabled=true;
const update=()=>{const p=preview();$('#live-check').innerHTML=checksHTML(p.o,p.i);};
const participants=()=>{const t=table($('[name="table"]').value);$('#participants').innerHTML=checksField('participants','Diners sharing this dish',t.diners,existingItem?.diners||(t.diners.length?[t.diners[0].id]:[]),'Choose more than one diner to mark a shared dish.')+(!t.diners.length?`<div class="warning-box mb">Add diners in the table view before placing an order.</div>`:'');update();};participants();$('#modal-form').addEventListener('change',e=>e.target.name==='table'?participants():update());}
function sendSummary(oid){const o=order(oid),draft=o.items.filter(i=>!i.submitted&&i.status!=='canceled'),clean=draft.filter(i=>!blocked(state,o,i)),hold=draft.filter(i=>blocked(state,o,i));modal('One final look','Each dish keeps its own dietary review and preparation status.',`<h3>${esc(table(o.table)?.name)} · Order #${o.id}</h3><div class="callout mt"><strong>${clean.length} ${clean.length===1?'dish can':'dishes can'} be received by the kitchen.</strong><p>${hold.length} ${hold.length===1?'dish remains':'dishes remain'} blocked and will appear separately as awaiting review. Sending does not approve them.</p></div>${draft.map(i=>`<div class="order-item"><div class="item-top"><strong>${i.quantity} × ${esc(dish(i.dish)?.name)}</strong><span class="badge ${blocked(state,o,i)?'amber':'green'}">${blocked(state,o,i)?'Blocked · review queue':'Ready to submit'}</span></div>${checksHTML(o,i,2)}</div>`).join('')}`,btn('Keep editing','close')+btn('Send order to kitchen '+icon('arrow'),'confirm-send','primary',`data-order="${o.id}"`));}
function reviewItem(oid,iid){allow(role,'review');const o=order(oid),i=o.items.find(x=>x.id===iid),d=dish(i.dish);formModal('Kitchen review',`${esc(table(o.table)?.name)} · #${o.id} · ${esc(d.name)}`,checksHTML(o,i)+selectField('mod','Preparation composition',[['','Standard recipe'],...d.modifications.filter(m=>m.reviewed).map(m=>[m.id,m.name])],i.mod)+`<div id="review-recheck"></div>`+selectField('outcome','Review outcome',['Reviewed preparation proposal','Cannot prepare under the requested conditions'],'Reviewed preparation proposal')+textField('notes','Composition, procedure & review notes','','Required. Describe the information used, composition changes, equipment and the reason for the outcome.')+`<div class="callout">A reviewed proposal never overrides an unresolved finding. Correct the composition or information and rerun checks. “Cannot prepare” cancels this dish and preserves the record.</div>`,fd=>mutate(()=>{allow(role,'review');const prev=i.mod;i.mod=fd.get('mod');if(prev!==i.mod)audit(state,role,'Kitchen preparation variant proposed',`#${o.id} / ${i.id}`,prev,i.mod);reconcile(state);review(state,o,i,fd.get('outcome'),String(fd.get('notes')),role);},'Kitchen assessment recorded. Unresolved findings remain blocked.'),{label:'Record review'});$('[name="mod"]').onchange=()=>{$('#review-recheck').innerHTML=checksHTML(o,{...i,mod:$('[name="mod"]').value});};}
function editIngredient(id){const prev=state.ingredients.find(x=>x.id===id),v=prev||{id:uid('ingredient'),name:'',aliases:'',contains:[],may:[],cross:[],subs:[],verified:false,supplier:'Fictional supplier',spec:'Illustrative specification pending',reviewDate:'2026-10-29'};const affected=prev?affectedDishes(state,id):[];const active=activeItems().filter(({i})=>affected.some(d=>d.id===i.dish));
formModal(prev?'Review ingredient information':'Create an ingredient','Changes propagate through compound ingredients and active orders.',`<div class="callout mb"><strong>Impact before saving</strong><p>${affected.length} dishes: ${affected.map(d=>esc(d.name)).join(', ')||'No dishes currently reference this ingredient.'}</p><p>${active.length} active order items will be checked again. Relevant reviews will be invalidated.</p></div><div class="field-row">${field('name','Ingredient name',v.name)}${field('aliases','Alternative names',v.aliases)}</div>${checksField('subs','Subingredients (compound ingredient)',state.ingredients.filter(i=>i.id!==v.id),v.subs,'Cycles are checked before saving; circular relationships are rejected.')}<div class="field-row">${checksField('contains','Contains allergens',state.allergens,v.contains)}${checksField('may','May contain',state.allergens,v.may)}</div>${checksField('cross','Possible ingredient cross-contact',state.allergens,v.cross)}<div class="field-row">${verifiedField(v.verified)}${field('reviewDate','Review date',v.reviewDate,'date')}</div><div class="field-row">${field('supplier','Fictional supplier',v.supplier)}${field('spec','Fictional specification sheet reference',v.spec)}</div>`,fd=>mutate(()=>{const value={...v,name:String(fd.get('name')).trim(),aliases:String(fd.get('aliases')),contains:fd.getAll('contains'),may:fd.getAll('may'),cross:fd.getAll('cross'),subs:fd.getAll('subs'),verified:fd.get('verified')==='true',supplier:String(fd.get('supplier')),spec:String(fd.get('spec')),reviewDate:String(fd.get('reviewDate'))};saveIngredient(state,value,role);},'Ingredient saved. Affected dishes and orders were rechecked.'),{wide:true});}
function editDish(id){const prev=dish(id),v=prev||{id:uid('dish'),name:'',description:'',category:state.settings.categories[0]||'Mains',price:0,image:'',status:'available',recipe:[],modifications:[],areas:[],cross:[],verified:false,version:1,reviewDate:'2026-10-29'};
const active=activeItems().filter(({i})=>i.dish===v.id);formModal(prev?'Edit dish & recipe':'Create a dish','Recipe changes recheck active orders. Allergens are computed from ingredients.',`<div class="callout mb"><strong>${active.length} active order items affected.</strong> Saving a relevant change invalidates previous reviews and reruns checks.</div><div class="field-row">${field('name','Dish name',v.name)}${field('price','Price (GBP)',v.price,'number')}</div>${textField('description','Description',v.description)}<div class="field-row">${selectField('category','Category',state.settings.categories,v.category)}${selectField('status','Availability',['available','sold out','deactivated'],v.status)}</div>${field('image','Illustrative image URL',v.image,'url','Use an HTTPS image URL. Images are illustrative, not a composition guarantee.')}<h3 class="mb">Recipe composition & optional quantities</h3><div class="check-list" style="max-height:280px;grid-template-columns:1fr">${state.ingredients.map(x=>`<div class="field-row" style="margin:0;align-items:center"><label class="check"><input type="checkbox" name="recipe" value="${x.id}" ${v.recipe.some(r=>r.ingredient===x.id)?'checked':''}>${esc(x.name)}</label><input class="input" name="qty-${x.id}" aria-label="Quantity of ${esc(x.name)}" placeholder="e.g. 100 g (optional)" value="${esc(v.recipe.find(r=>r.ingredient===x.id)?.quantity||'')}" style="font-size:10px;min-height:30px;padding:6px"></div>`).join('')}</div><hr class="subtle-line">${checksField('areas','Preparation equipment / areas',state.areas,v.areas)}${checksField('cross','Dish-level possible cross-contact',state.allergens,v.cross)}<div class="field-row">${verifiedField(v.verified)}${field('reviewDate','Last reviewed',v.reviewDate,'date')}</div><h3 class="mb">Configured & reviewed modifications</h3><p class="help-text mb">One line per permitted variant: Name | ingredient IDs to remove | ingredient IDs to add | reviewed or pending. Only reviewed variants appear in order entry.</p>${textField('mods','Permitted modifications',v.modifications.map(m=>`${m.name} | ${m.remove.join(',')} | ${m.add.join(',')} | ${m.reviewed?'reviewed':'pending'}`).join('\n'))}<details class="help-text mb"><summary>Ingredient identifiers for modification configuration</summary>${state.ingredients.map(i=>`${esc(i.id)}: ${esc(i.name)}`).join('<br>')}</details>`,fd=>mutate(()=>{allow(role,'catalog');const mods=String(fd.get('mods')).split('\n').filter(x=>x.trim()).map((line,index)=>{const [name='',remove='',add='',reviewed='pending']=line.split('|').map(x=>x.trim());if(!name)throw Error('Each variant needs a name.');const m={id:v.modifications[index]?.id||uid('mod'),name,remove:remove.split(',').map(x=>x.trim()).filter(Boolean),add:add.split(',').map(x=>x.trim()).filter(Boolean),reviewed:reviewed==='reviewed'};if([...m.remove,...m.add].some(id=>!state.ingredients.some(i=>i.id===id)))throw Error('A modification refers to an unknown ingredient ID.');if(m.remove.some(id=>!fd.getAll('recipe').includes(id)))throw Error('Removed ingredients must be roots of this recipe.');return m;});const value={...v,name:String(fd.get('name')).trim(),description:String(fd.get('description')),category:fd.get('category'),price:+fd.get('price'),image:String(fd.get('image')).trim(),status:fd.get('status'),recipe:fd.getAll('recipe').map(ingredient=>({ingredient,quantity:String(fd.get('qty-'+ingredient)||''),removable:false})),modifications:mods,areas:fd.getAll('areas'),cross:fd.getAll('cross'),verified:fd.get('verified')==='true',reviewDate:fd.get('reviewDate'),version:v.version+(prev?1:0)};if(!value.recipe.length)throw Error('A recipe needs at least one ingredient.');if(!Number.isFinite(value.price)||value.price<0)throw Error('Price must be a nonnegative number.');if(value.image&&!/^https:\/\//i.test(value.image))throw Error('Use an HTTPS image URL.');if(prev)state.dishes[state.dishes.indexOf(prev)]=value;else state.dishes.push(value);audit(state,role,'Dish recipe saved',value.name,prev,value);},'Dish saved and all affected orders checked again.'),{wide:true});}
function editAllergen(id){const prev=state.allergens.find(a=>a.id===id),v=prev||{id:uid('allergen'),name:'',aliases:'',active:true};formModal('Allergen catalog','Identifiers are retained when names or aliases change.',field('name','Allergen name',v.name)+field('aliases','Alternative names (comma separated)',v.aliases)+`<div class="callout">Archiving removes an allergen from new selection lists while preserving existing ingredient relationships, diner declarations, order snapshots and detection.</div>`,fd=>mutate(()=>{allow(role,'catalog');const value={...v,name:String(fd.get('name')).trim(),aliases:String(fd.get('aliases'))};if(!value.name)throw Error('Name is required.');if(prev)state.allergens[state.allergens.indexOf(prev)]=value;else state.allergens.push(value);audit(state,role,'Allergen catalog updated',value.name,prev,value);},'Allergen updated. References were preserved.'));}
function editArea(id){const prev=state.areas.find(a=>a.id===id),v=prev||{id:uid('area'),name:'',allergens:[],verified:false,notes:''};const impacted=state.dishes.filter(d=>d.areas.includes(v.id));formModal('Cross-contact information','Equipment and preparation risks are independent of recipe ingredient removal.',`<div class="callout mb">Affected dishes: ${impacted.map(d=>esc(d.name)).join(', ')||'No dishes linked yet.'}. Active orders using these dishes will be checked again.</div>`+field('name','Equipment / preparation area',v.name)+checksField('allergens','Possible cross-contact',state.allergens,v.allergens)+verifiedField(v.verified)+textField('notes','Procedure & information requiring review',v.notes),fd=>mutate(()=>{allow(role,'catalog');const value={...v,name:String(fd.get('name')).trim(),allergens:fd.getAll('allergens'),verified:fd.get('verified')==='true',notes:String(fd.get('notes'))};if(!value.name)throw Error('Name is required.');if(prev)state.areas[state.areas.indexOf(prev)]=value;else state.areas.push(value);audit(state,role,'Cross-contact information updated',value.name,prev,value);},'Cross-contact information saved. Relevant orders were rechecked.'));}
function editUser(id){const prev=state.users.find(u=>u.id===id),v=prev||{id:uid('user'),name:'',role:'Waitstaff',active:true};formModal('Demonstration profile','Profiles define who is recorded as the author of simulated actions.',field('name','Profile display name',v.name)+selectField('role','Permission role',['Waitstaff','Kitchen','Administration'],v.role)+selectField('active','Profile status',[['true','Enabled'],['false','Disabled']],String(v.active))+`<div class="callout">Role permissions are defined in the application. Assigning Kitchen grants review and preparation actions; Administration grants recipe, catalog and profile management. This is simulated access.</div>`,fd=>mutate(()=>{allow(role,'catalog');const value={...v,name:String(fd.get('name')).trim(),role:fd.get('role'),active:fd.get('active')==='true'};if(prev?.role==='Administration'&&(!value.active||value.role!=='Administration')&&!state.users.some(u=>u.id!==prev.id&&u.role==='Administration'&&u.active))throw Error('Keep at least one active administration profile.');if(prev)state.users[state.users.indexOf(prev)]=value;else state.users.push(value);audit(state,role,'Demonstration profile updated',value.name,prev,value);},'Profile saved.'));}
function editTable(id){const prev=table(id),v=prev||{id:uid('table'),name:'',capacity:4,zone:'Main dining',session:uid('session'),diners:[]};formModal('Table settings','Tables retain their diner and order references.',field('name','Table name or number',v.name)+field('capacity','Seats',v.capacity,'number')+field('zone','Dining area',v.zone),fd=>mutate(()=>{allow(role,'table');const value={...v,name:String(fd.get('name')).trim(),capacity:+fd.get('capacity'),zone:String(fd.get('zone'))};if(!Number.isInteger(value.capacity)||value.capacity<1||value.capacity>30)throw Error('Seats must be 1–30.');if(state.tables.some(t=>t.id!==v.id&&t.name===value.name))throw Error('A table with this name already exists.');if(prev)state.tables[state.tables.indexOf(prev)]=value;else state.tables.push(value);audit(state,role,'Table configuration updated',value.name,prev,value);},'Table saved.'));}
function sampleScenarios(){modal('A few ways to explore','Load a fictional case at Table 10, then follow the expected outcome.',`<div class="notice">${icon('alert')}Loading a scenario replaces the current Table 10 service. Previous Table 10 orders are canceled and retained with their snapshots.</div><div class="scenario-grid">${scenarios.map(([id,title,desc],n)=>`<article class="scenario-card"><span class="scenario-number">SCENARIO ${String(n+1).padStart(2,'0')}</span><h3>${title}</h3><p>${desc}</p>${btn('Load sample scenario '+icon('arrow'),'load-scenario','sm',`data-key="${id}"`)}</article>`).join('')}</div>`,btn('Close','close'),true);}
function help(){modal('A little more context','Mise is a working demonstration using fictional, unvalidated data.',`<div class="callout mb">Demonstration using fictional data. Do not use to manage real allergies without validation and restaurant procedures.</div><h3>Try a complete service</h3><ol class="help-text"><li>Choose a table and record a declaration for each diner.</li><li>Add dishes and permitted variants. Shared plates check every selected diner.</li><li>Review & send. Unblocked dishes enter the kitchen; affected dishes enter the review queue.</li><li>Switch to Kitchen, inspect the composition, record a review and progress eligible dishes.</li><li>Switch to Administration to edit recipes, equipment risks and supplier review information. Affected orders are rechecked.</li></ol><h3 class="mt">Simulated roles, local persistence</h3><p class="help-text mt">The role selector simulates access. Production requires server-side authentication and authorization. There is no server or real multiuser infrastructure. Data is stored in this browser’s localStorage and synchronizes between tabs on the same origin. Separate browsers and devices do not share data. Concurrent writes use last-write-wins; this is unsuitable for live restaurant service.</p><h3 class="mt">Reviews and blocked dishes</h3><p class="help-text mt">Recording a review does not override direct matches, potential risks or incomplete information. Correct the underlying information or composition, then rerun checks. Relevant changes invalidate earlier reviews. No-match results are not a suitability guarantee. The app offers no medical recommendations.</p><h3 class="mt">Privacy & limitations</h3><p class="help-text mt">Use simple diner identifiers. Reset clears diner information and restores fictional data. Supplier references and menu images are illustrative; no real certification, verification, payments, external notifications or credential-based integrations are implemented. Preparation status identifiers and role permission rules are fixed; display labels and profile role assignments are editable.</p>`,btn('Explore sample scenarios','scenarios','primary')+btn('Close','close'),true);}
function reviewHistory(){modal('Kitchen review history','Each review retains its author, timestamp and information snapshot.',`<div class="timeline">${state.orders.flatMap(o=>o.items.flatMap(i=>i.reviews.map(r=>({o,i,r})))).sort((a,b)=>new Date(b.r.at)-new Date(a.r.at)).map(({o,i,r})=>`<article class="history-entry"><h4>${esc(dish(i.dish)?.name)} · #${o.id} ${r.invalidated||r.fingerprint!==fingerprint(state,o,i)?'<span class="badge amber">Invalidated</span>':'<span class="badge green">Recorded</span>'}</h4><p>${esc(r.outcome)} · ${esc(r.author)} · ${fmt(r.at)}</p><p>${esc(r.notes)}</p><details><summary>View information used for review</summary><pre>${esc(JSON.stringify(r.snapshot,null,2))}</pre></details></article>`).join('')||'<div class="empty-state">No kitchen reviews have been recorded yet.</div>'}</div>`,btn('Close','close'),true);}
function snapshots(){modal('Order information snapshots','Recipe versions, diners, ingredient paths and findings retained at each relevant check.',state.orders.map(o=>`<div class="history-entry"><h4>Order #${o.id} · ${esc(table(o.table)?.name)}</h4>${o.items.map(i=>`<details><summary>${esc(dish(i.dish)?.name)} · ${i.snapshots.length} snapshot(s)</summary><pre>${esc(JSON.stringify(i.snapshots,null,2))}</pre></details>`).join('')}</div>`).join(''),btn('Close','close'),true);}
function alternative(oid,iid){const o=order(oid),i=o.items.find(x=>x.id===iid);modal('Explore an alternative','Every suggestion is checked against the same diners and current information.',`<p class="help-text mb">Replacing ${esc(dish(i.dish)?.name)} for ${i.diners.map(id=>esc(table(o.table)?.diners.find(d=>d.id===id)?.name)).join(' + ')}. No alternative is guaranteed suitable.</p>${state.dishes.filter(d=>d.status==='available'&&d.id!==i.dish).map(d=>{const findings=check(state,o,{...i,dish:d.id,mod:''});return`<div class="summary-row"><div><strong>${esc(d.name)}</strong><p class="help-text">${findings.length?`${findings.length} finding(s) — review needed`:'No matches detected · not a guarantee'}</p></div>${btn('Choose','choose-alternative','sm',`data-order="${oid}" data-item="${iid}" data-dish="${d.id}"`)}</div>`;}).join('')}`,btn('Close','close'));}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action;try{
if(a==='close')return closeModal();if(a==='nav')return nav(b.dataset.page);if(a==='table')return nav('table',b.dataset.id);
if(a==='help')return help();if(a==='scenarios')return sampleScenarios();if(a==='review-history')return reviewHistory();if(a==='snapshots')return snapshots();
if(a==='floor-filter'){tableFilter=b.dataset.value;return render();}if(a==='category'){menuCategory=b.dataset.value;return render();}if(a==='order-filter'){orderFilter=b.dataset.value;return render();}if(a==='kitchen-filter'){kitchenFilter=b.dataset.value;return render();}if(a==='admin-tab'){adminTab=b.dataset.value;return render();}
if(a==='new-order')return newOrder();if(a==='table-menu'){selectedTable=b.dataset.id;return nav('menu');}
if(a==='add-diner')return editDiner(b.dataset.table);if(a==='edit-diner')return editDiner(b.dataset.table,b.dataset.id);
if(a==='dish-detail')return dishDetail(b.dataset.id);if(a==='add-dish')return addDish(b.dataset.id);
if(a==='item-detail'){const o=order(b.dataset.order),i=o.items.find(i=>i.id===b.dataset.item);return dishDetail(i.dish,o,i);}
if(a==='edit-item'){const o=order(b.dataset.order),i=o.items.find(i=>i.id===b.dataset.item);return addDish(i.dish,o,i);}
if(a==='remove-item'){return mutate(()=>{allow(role,'order');const o=order(b.dataset.order),i=o.items.find(i=>i.id===b.dataset.item);if(i.submitted)throw Error('Submitted dishes must be canceled by the kitchen and retained in history.');audit(state,role,'Draft dish removed',`#${o.id}`,i,null);o.items=o.items.filter(x=>x.id!==i.id);},'Dish removed.');}
if(a==='request-review')return mutate(()=>{allow(role,'request');const o=order(b.dataset.order),i=o.items.find(x=>x.id===b.dataset.item);i.requested=true;i.submitted=true;i.status='awaiting review';audit(state,role,'Kitchen review requested',`#${o.id} / ${i.id}`,null,'Review requested');},'Kitchen review requested. The dish remains blocked.');
if(a==='send-summary')return sendSummary(b.dataset.order);if(a==='confirm-send')return mutate(()=>submit(state,order(b.dataset.order),role),'Order sent. Blocked dishes are separated in the kitchen queue.');
if(a==='review-item')return reviewItem(b.dataset.order,b.dataset.item);
if(a==='transition')return mutate(()=>{const o=order(b.dataset.order),i=o.items.find(i=>i.id===b.dataset.item);transition(state,o,i,b.dataset.next,role);},'Preparation status updated.');
if(a==='edit-ingredient'){allow(role,'catalog');return editIngredient(b.dataset.id);}if(a==='edit-dish'){allow(role,'catalog');return editDish(b.dataset.id);}if(a==='edit-allergen'){allow(role,'catalog');return editAllergen(b.dataset.id);}if(a==='edit-area'){allow(role,'catalog');return editArea(b.dataset.id);}if(a==='edit-user'){allow(role,'catalog');return editUser(b.dataset.id);}if(a==='edit-table'){allow(role,'table');return editTable(b.dataset.id);}
if(a==='duplicate-dish')return mutate(()=>{allow(role,'catalog');const d=clone(dish(b.dataset.id));d.id=uid('dish');d.name+=' (copy)';d.status='deactivated';d.version=1;state.dishes.push(d);audit(state,role,'Dish duplicated',d.name,null,d);},'Dish duplicated as deactivated. Edit it before activation.');
if(a==='toggle-dish')return mutate(()=>{allow(role,'catalog');const d=dish(b.dataset.id),prev=d.status;d.status=d.status==='deactivated'?'available':'deactivated';audit(state,role,'Dish availability changed',d.name,prev,d.status);},'Dish availability saved.');
if(a==='archive-allergen')return mutate(()=>{allow(role,'catalog');const a=state.allergens.find(a=>a.id===b.dataset.id),prev=a.active;a.active=!a.active;audit(state,role,a.active?'Allergen restored':'Allergen archived',a.name,prev,a.active);},'Catalog updated. Existing relationships and warnings were preserved.');
if(a==='load-scenario'){let o;const okay=mutate(()=>{allow(role,'order');for(const old of state.orders.filter(o=>o.table==='table-10'))for(const i of old.items)if(!['served','canceled'].includes(i.status)){audit(state,role,'Previous sample session canceled',`#${old.id}`,i.status,'canceled');i.status='canceled';}o=loadScenario(state,b.dataset.key,role);},'Sample scenario loaded at Table 10.');if(okay)nav('table',o.table);return;}
if(a==='scenario-change')return mutate(()=>{const o=order(b.dataset.order);if(o.scenario==='late'){allow(role,'diner');const d=table(o.table).diners[0],prev=clone(d);d.state='declared';d.restrictions=[{type:'allergy',target:'ingredient',id:'oil'}];audit(state,role,'Late ingredient restriction recorded',d.name,prev,d);}else{allow(role,'catalog');const ingredient=clone(state.ingredients.find(i=>i.id==='lemon'));ingredient.contains=[...new Set([...ingredient.contains,'milk'])];saveIngredient(state,ingredient,role);}},'Scenario change applied. The previous review is invalidated.');
if(a==='alternative')return alternative(b.dataset.order,b.dataset.item);if(a==='choose-alternative'){const o=order(b.dataset.order),i=o.items.find(x=>x.id===b.dataset.item);return mutate(()=>{allow(role,'order');if(['in preparation','ready','served','canceled'].includes(i.status))throw Error('This dish cannot be replaced at its current status.');const prev=clone(i);i.dish=b.dataset.dish;i.mod='';audit(state,role,'Alternative dish chosen',`#${o.id}`,prev,i);},'Alternative selected and checked. No suitability guarantee is implied.');}
if(a==='export-data'){allow(role,'catalog');const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='mise-fictional-demo.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return toast('Fictional demonstration data exported.');}
if(a==='reset-confirm'){allow(role,'reset');return modal('Reset the demonstration?','This clears the current diner information in this browser.',`<p class="help-text">All current diners, declarations, notes, orders, reviews and change history will be removed from the demonstration store. Fictional sample data will then be restored. Other open tabs on the same origin will receive the reset.</p><div class="notice mt">${icon('alert')}Previously downloaded exports and copied data are outside this reset.</div>`,btn('Keep my demo','close')+btn('Clear data & restore samples','reset-data','danger'));}
if(a==='reset-data')return mutate(()=>{allow(role,'reset');state=seed();selectedTable='table-4';},'Diner data cleared. Fictional demonstration restored.');
}catch(err){toast(err.message,true);}});
document.addEventListener('change',e=>{if(e.target.id==='role-select'){role=e.target.value;sessionStorage.setItem('mise-role',role);if(!state.users.some(u=>u.role===role&&u.active))toast('No active profile is configured for this role. Actions will be unavailable until an administrator enables one.',true);if(page==='admin'&&role!=='Administration')page='dashboard';render();}});
document.addEventListener('input',e=>{if(e.target.id==='menu-search'){const pos=e.target.selectionStart;menuSearch=e.target.value;render();const input=$('#menu-search');input.focus();input.setSelectionRange(pos,pos);}});
document.addEventListener('submit',e=>{if(e.target.id==='status-form'){e.preventDefault();const fd=new FormData(e.target);mutate(()=>{allow(role,'settings');const prev=clone(state.settings.statusLabels||{});const labels=Object.fromEntries(state.settings.statuses.map(x=>[x,String(fd.get('status-'+x)).trim()]));if(Object.values(labels).some(x=>!x))throw Error('Every status needs a display label.');state.settings.statusLabels=labels;audit(state,role,'Status display labels updated','Preparation statuses',prev,labels);},'Status labels saved. Transition and blocking rules remain enforced.');return;}if(e.target.id!=='settings-form')return;e.preventDefault();const fd=new FormData(e.target);mutate(()=>{allow(role,'settings');const prev=clone(state.settings);state.settings.restaurant=String(fd.get('restaurant')).trim();state.settings.service=String(fd.get('service')).trim();state.settings.categories=[...new Set([...String(fd.get('categories')).split(',').map(x=>x.trim()).filter(Boolean),...state.dishes.map(d=>d.category)])];state.settings.procedure=String(fd.get('procedure')).trim();if(!state.settings.restaurant||!state.settings.procedure)throw Error('Restaurant and review procedure are required.');audit(state,role,'Restaurant settings updated','Settings',prev,state.settings);},'Settings saved. Relevant procedure changes require fresh reviews.');});
document.addEventListener('keydown',e=>{if(!$('.modal'))return;if(e.key==='Escape')closeModal();if(e.key==='Tab'){const all=[...$('.modal').querySelectorAll('button:not(:disabled),input,select,textarea,[tabindex="0"],summary')].filter(x=>x.getClientRects().length);const first=all[0],last=all.at(-1);if(e.shiftKey&&(document.activeElement===first||document.activeElement===$('.modal'))){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
window.addEventListener('storage',e=>{if(e.key!==KEY)return;try{const incoming=JSON.parse(e.newValue);if(incoming?.schema===1){state=incoming;closeModal();render();toast('This view was updated from another demonstration tab.');}}catch{toast('An external storage update could not be read.',true);}});
window.addEventListener('hashchange',()=>{const [p,t]=location.hash.slice(1).split('/');if(['dashboard','menu','orders','kitchen','reviews','admin','table'].includes(p)){page=p;if(t&&table(t))selectedTable=t;render();}});
const [initial,initialTable]=location.hash.slice(1).split('/');if(['dashboard','menu','orders','kitchen','reviews','admin','table'].includes(initial))page=initial;if(initialTable&&table(initialTable))selectedTable=initialTable;
save();render();setInterval(()=>{if(!$('.modal')&&!['menu','admin','table'].includes(page))render();},60000);
